const rows = $input.all().map(function (i) { return i.json; });
const now = Date.now();
const HR = 3600000;
function ms(t) { const d = Date.parse(t); return isNaN(d) ? 0 : d; }
const toScore = rows.filter(function (r) { return r.status === 'to_score'; });
const scoring = rows.filter(function (r) { return r.status === 'scoring'; });
const deep = rows.filter(function (r) { return r.status === 'needs_deep_fetch'; });
const errs = rows.filter(function (r) { return r.status === 'error_held'; });
let lastScored = 0;
rows.forEach(function (r) { if (r.status === 'scored') { const t = ms(r.screened_at); if (t > lastScored) lastScored = t; } });
const alerts = [];
if (toScore.length > 0 && (lastScored === 0 || (now - lastScored) > 26 * HR)) { alerts.push('\u2022 *Scorer may not have run*: ' + toScore.length + ' row(s) waiting in to_score; last verdict ' + (lastScored ? new Date(lastScored).toISOString() : 'never') + '.'); }
const stuck = scoring.filter(function (r) { const t = ms(r.claim_at); return t && (now - t) > HR; });
if (stuck.length > 0) { alerts.push('\u2022 *Stuck scoring*: ' + stuck.length + ' row(s) held >60m (dead lease) \u2014 reclaim next run.'); }
let oldestDeep = 0;
deep.forEach(function (r) { const t = ms(r.fetched_at); if (t && (oldestDeep === 0 || t < oldestDeep)) oldestDeep = t; });
if (deep.length > 0 && oldestDeep && (now - oldestDeep) > 7 * 24 * HR) { alerts.push('\u2022 *Deep-Fetch Queue aging*: ' + deep.length + ' row(s), oldest ' + Math.floor((now - oldestDeep) / (24 * HR)) + 'd \u2014 needs the 9222 pass.'); }
if (errs.length > 0) { alerts.push('\u2022 *Error-held*: ' + errs.length + ' row(s) need a look.'); }
if (alerts.length === 0) return [];
const msg = '\uD83D\uDEA8 *SCORING WATCHDOG* ' + new Date().toISOString().slice(0, 10) + '\n' + alerts.join('\n');
return [{ json: { alert: msg, alert_count: alerts.length } }];
